# Long-case expansion L3 (target ~30 Qs): SJS/TEN, urticaria, ichthyosis, NF1, tuberous sclerosis.
# Own words; viva-length answers. Facts from IADVL 5e and standard references.
D = [
dict(case="Stevens–Johnson syndrome / TEN", qa=[
 ("What is the latency period and why is it important?", ["Usually 4–28 days after starting a new drug (first exposure); rechallenge can cause reaction within 48 h; drugs started >8 weeks earlier or used safely for years are unlikely culprits (except dose change) — key in ALDEN"]),
 ("Describe the eye care protocol in SJS/TEN.", ["Daily ophthalmology review from admission: preservative-free lubricants hourly, topical steroid drops (prednisolone acetate) and antibiotic drops, glass-rod sweeping/lysis of conjunctival adhesions, scleral shells/ symblepharon rings", "Amniotic membrane transplantation within first week for significant ocular surface sloughing — reduces chronic sequelae; long-term follow-up for dry eye, trichiasis, limbal stem cell deficiency"]),
 ("What are the oral, genital and respiratory care measures?", ["Mouth: warm saline/ antiseptic (chlorhexidine) mouthwashes, anaesthetic gels/ benzydamine, steroid mouthwash, white soft paraffin to lips; soft or nasogastric feeds", "Genital: daily examination, potent topical steroid ointment, non-adherent dressings, vaginal dilators/ moulds to prevent synechiae; urinary catheter if needed", "Respiratory: monitor oxygen saturation, chest X-ray, early intubation if bronchial involvement (poor prognosis)"]),
 ("What fluid regimen is used?", ["Less than burns because dermis is intact: about 2 ml/kg/% BSA detached in first 24 h (plus maintenance) or titrated to urine output 0.5–1 ml/kg/h; prefer crystalloids, add albumin if low; avoid fluid overload; peripheral lines through unaffected skin"]),
 ("Why are prophylactic antibiotics not given?", ["They select resistant organisms and increase drug-reaction risk; instead take skin/ blood/ urine/ catheter-tip cultures every 48 h and treat promptly when sepsis signs appear (fever may be absent — watch for hypothermia, falling BP, confusion, rising glucose, falling urine output)"]),
 ("Discuss the cyclosporine regimen and evidence.", ["3–5 mg/kg/day orally in two divided doses for 7–10 days then taper over a month — inhibits T-cell activation and granulysin release; multiple cohort studies and meta-analyses show lower mortality than predicted by SCORTEN; first-line in our protocol; monitor BP, renal function, electrolytes"]),
 ("What is the role of systemic corticosteroids?", ["Controversial: early short high-dose pulses (dexamethasone 1.5 mg/kg/day for 3 days or methylprednisolone 1 g/day for 3 days) may halt progression when given within 72 h; prolonged steroids increase sepsis and mortality; commonly combined with IVIG or cyclosporine in Indian practice"]),
 ("What are the HLA screening recommendations?", ["HLA-B*15:02 testing before carbamazepine/ oxcarbazepine in patients of Han Chinese, Thai, Malaysian, Indonesian and some Indian ancestry; HLA-B*58:01 before allopurinol in Han Chinese, Korean, Thai, and those with CKD; HLA-B*57:01 before abacavir (hypersensitivity syndrome)"]),
 ("Which drugs cause SJS/TEN in HIV patients?", ["Nevirapine (first 6–8 weeks), cotrimoxazole (prophylaxis), anti-TB drugs, fluconazole; HIV increases SJS/TEN risk up to 1000-fold; manage carefully when restarting ART (avoid nevirapine permanently)"]),
 ("Paediatric SJS/TEN — causes and differences.", ["Drugs: sulphonamides, antiepileptics (phenobarbitone, carbamazepine, lamotrigine), paracetamol (debated), NSAIDs; infections — Mycoplasma (MIRM), HSV; lower mortality than adults; ocular sequelae equally serious"]),
 ("Discuss SJS/TEN in pregnancy.", ["Risk to mother and fetus (preterm birth); supportive care in burns/ICU; avoid teratogenic immunomodulators; IVIG and steroids preferred; neonatal TEN possible; vaginal synechiae may complicate delivery"]),
 ("How do you differentiate SSSS from TEN histologically and clinically?", ["SSSS: children/renal failure, tender erythema starting periorificially and flexures, superficial peeling, no mucosal involvement, Nikolsky positive on normal skin; split at granular layer (frozen section of peeled skin — only stratum corneum and granular layer); antibiotics", "TEN: drug history, mucosa involved, full-thickness epidermal necrosis on frozen section, deeper detachment; stop drug, burns-unit care"]),
 ("What is the pharmacovigilance pathway in India?", ["Report the ADR to the nearest ADR Monitoring Centre under Pharmacovigilance Programme of India (PvPI, Indian Pharmacopoeia Commission) via suspected ADR reporting form/ ADR PvPI app or toll-free helpline; causality (WHO-UMC/Naranjo) documented"]),
 ]),
dict(case="Urticaria & angioedema", qa=[
 ("Explain mast cell activation and mediators in detail (PYQ: chemical mediators of urticaria).", ["Preformed (granule): histamine (H1 — wheal, flare, itch), tryptase, chymase, heparin, TNF-α", "Newly synthesised: prostaglandin D2, leukotrienes C4/D4/E4, PAF", "Cytokines/chemokines: IL-4, IL-5, IL-13, IL-31 — late-phase and itch", "Triggers: IgE–FcεRI cross-linking (allergen/ autoantibodies), complement C5a, MRGPRX2 receptor (opioids, neuromuscular blockers, quinolones, icatibant, contrast — pseudo-allergic), substance P, physical stimuli"]),
 ("Discuss physical urticarias other than cold and cholinergic.", ["Symptomatic dermographism (commonest — linear wheals after scratching)", "Delayed pressure urticaria (deep painful swellings 4–8 h after pressure — soles, buttocks, shoulder straps; poor antihistamine response — dapsone, omalizumab)", "Heat urticaria (local wheals after heat contact), solar urticaria (within minutes of sun/visible light — phototesting, omalizumab, hardening), vibratory angioedema (ADGRE2), aquagenic urticaria (small perifollicular wheals after water contact)"]),
 ("What is NSAID-exacerbated urticaria?", ["COX-1 inhibition shifts arachidonic acid to leukotriene pathway — aspirin/NSAIDs worsen chronic urticaria in 20–30% of CSU patients; advise paracetamol or selective COX-2 inhibitors (celecoxib/etoricoxib) instead; NSAID-induced urticaria/angioedema can occur in non-CSU patients too"]),
 ("Describe the role of diet in chronic urticaria.", ["True food allergy rarely causes chronic urticaria; pseudoallergen-free diet (avoid additives, preservatives, colouring, natural salicylates) for 3–6 weeks may help some patients; avoid unnecessary restriction"]),
 ("Omalizumab — mechanism and use in CSU.", ["Anti-IgE monoclonal antibody — binds free IgE → reduces FcεRI on mast cells/basophils → less activation; 300 mg SC every 4 weeks (can up-dose to 450–600 mg or every 2 weeks); response in ~70%, faster in type I autoallergic CSU (high IgE); safe in pregnancy; anaphylaxis rare"]),
 ("Cyclosporine in CSU.", ["3.5–5 mg/kg/day for 3–6 months for omalizumab non-responders (better in type IIb autoimmune CSU — low IgE, positive basophil test/ ASST); monitor BP, creatinine; taper slowly"]),
 ("What is autologous serum skin test (ASST)?", ["0.05 ml of patient's own serum injected intradermally vs saline and histamine controls; red wheal ≥1.5 mm larger than saline at 30 min = positive — suggests autoimmune (functional histamine-releasing autoantibodies) urticaria; stop antihistamines 2–3 days before; supports diagnosis but not essential"]),
 ("What is urticaria in pregnancy and children — treatment?", ["Pregnancy: loratadine or cetirizine (best data), avoid up-dosing beyond needed; omalizumab acceptable if severe", "Children: second-generation antihistamines (cetirizine, levocetirizine, desloratadine, fexofenadine, bilastine) dosed by age/weight; acute urticaria usually viral; chronic urticaria — screen thyroid autoimmunity, coeliac if indicated"]),
 ("What is Schnitzler syndrome?", ["Chronic non-itchy urticarial rash + monoclonal IgM (or IgG) gammopathy + recurrent fever, bone pain, arthralgia, lymphadenopathy, raised CRP; neutrophilic urticarial dermatosis on biopsy; responds dramatically to IL-1 blockade (anakinra, canakinumab); risk of lymphoproliferative disease"]),
 ("Autoinflammatory urticaria-like syndromes.", ["Cryopyrin-associated periodic syndromes (CAPS — NLRP3: FCAS, Muckle–Wells, NOMID/CINCA) — urticarial rash from infancy, fever, conjunctivitis, deafness, amyloidosis; adult-onset Still's disease (evanescent salmon rash), Schnitzler — treat with IL-1 inhibitors"]),
 ("What is mastocytosis and how to differentiate from urticaria?", ["Clonal mast cell disease (KIT D816V); urticaria pigmentosa/ maculopapular cutaneous mastocytosis — brown macules/ papules that urticate on rubbing (Darier's sign), mastocytoma (child), systemic forms — flushing, anaphylaxis, raised baseline tryptase (>20 ng/ml)", "Urticaria: transient wheals without residual pigment, normal tryptase"]),
 ("Angioedema without wheals — approach.", ["Ask about drugs (ACE inhibitors, gliptins, NSAIDs, oestrogens), family history, abdominal attacks; check C4 (low in HAE/acquired C1-INH deficiency), C1-INH level/function, C1q (low in acquired — lymphoproliferative/ autoimmune); normal complements → idiopathic histaminergic (responds to antihistamines) or ACE-inhibitor/ HAE with normal C1-INH"]),
 ("Contact urticaria — differentiate from chronic urticaria.", ["Contact urticaria: wheals only at contact site within minutes–1 h, triggered by specific substances (latex, foods, cosmetics, plants), may progress to generalised urticaria/ anaphylaxis (immunological); diagnosis by open/prick tests; avoidance"]),
 ("What is the urticaria activity score (UAS7) cutoff?", ["UAS7 = sum over 7 days of daily wheal score (0–3) + itch score (0–3), maximum 42: 0 urticaria-free, 1–6 well controlled, 7–15 mild, 16–27 moderate, 28–42 severe; UCT ≥12 = well controlled (4-week recall)"]),
 ("Prognosis of chronic inducible urticaria.", ["Often persists longer than CSU (years); dermographism and cold urticaria may last 5–10 years; avoidance and regular antihistamines control most"]),
 ]),
dict(case="Ichthyosis", qa=[
 ("Define ichthyosis and the difference between inherited and acquired.", ["Disorders of cornification with generalised scaling (fish-like scale) due to abnormal epidermal differentiation/ barrier function", "Inherited: present at birth or early childhood; acquired: adult onset — associated with lymphoma (Hodgkin), malignancy, HIV, sarcoidosis, leprosy, hypothyroidism, malnutrition, CKD, drugs (nicotinic acid, statins, clofazimine, cimetidine, kava, hydroxyurea)"]),
 ("Describe the clinical approach to a child with scaling from birth.", ["Was there a collodion membrane (ARCI)? Blisters at birth (epidermolytic)? Erythroderma? Hair shaft abnormality (Netherton)? Neurological/ eye signs (Sjögren–Larsson, Refsum)? Family history and pattern (X-linked — boys; AR — consanguinity)", "Examine distribution (flexures spared in IV), scale type (fine white vs large dark plate-like), palms/soles (hyperlinearity — IV), ectropion/eclabium, alopecia, nails, sweating"]),
 ("Ichthyosis vulgaris — pathogenesis and associations.", ["Semi-dominant FLG loss-of-function mutations → reduced filaggrin → reduced NMF, poor hydration; reduced keratohyaline granules (thin/absent granular layer on histology)", "Associations: atopic dermatitis (up to 50%), keratosis pilaris, palmar hyperlinearity, allergic rhinitis/ asthma"]),
 ("X-linked recessive ichthyosis — more details.", ["Steroid sulfatase (STS) deficiency on Xp22.3 (mostly whole-gene deletion) → cholesterol sulfate accumulation in stratum corneum → retention hyperkeratosis", "Boys: large dark-brown 'dirty' adherent scales on neck ('dirty neck'), trunk, extensor limbs, with flexural involvement possible; palms/soles spared; corneal opacities (also in carrier mothers), cryptorchidism, testicular cancer risk, ADHD/ autism; contiguous gene deletion — Kallmann syndrome (anosmia, hypogonadism)", "Mothers: low oestriol in pregnancy, prolonged labour (placental STS deficiency); diagnosis — STS enzyme assay, FISH/ microarray, cholesterol sulfate on lipoprotein electrophoresis (increased β-LDL mobility)"]),
 ("Lamellar ichthyosis vs congenital ichthyosiform erythroderma.", ["Both autosomal recessive congenital ichthyosis (ARCI) — TGM1 (transglutaminase 1), ALOX12B, ALOXE3, NIPAL4, CYP4F22, ABCA12", "Lamellar: collodion baby, then large, plate-like dark brown scales, minimal erythema, ectropion, eclabium, alopecia, hypohidrosis/ heat intolerance", "CIE: fine white scales with prominent erythroderma; less ectropion", "Self-improving collodion ichthyosis — mild residual phenotype"]),
 ("Describe the management of a collodion baby.", ["Neonatal ICU, humidified incubator (high humidity), temperature regulation, fluid and electrolyte monitoring (hypernatraemic dehydration), sepsis watch, bland emollients (white soft paraffin), avoid keratolytics (salicylate toxicity), eye care for ectropion, feeding support; membrane sheds in 2–4 weeks"]),
 ("Harlequin ichthyosis — features and management.", ["Most severe ARCI — ABCA12 mutation (lipid transporter in lamellar granules); thick plate-like scales separated by deep red fissures, severe ectropion, eclabium, flattened ears, restricted movement, respiratory/ feeding difficulty, sepsis", "Management: NICU, oral retinoids (acitretin 0.5–1 mg/kg) early improve survival, emollients, ophthalmic care; survival into adulthood now possible with severe erythroderma phenotype"]),
 ("Epidermolytic ichthyosis — genetics and features.", ["Autosomal dominant KRT1/KRT10 mutations (keratin 1/10 — suprabasal keratins); at birth erythroderma with blisters and erosions; later corrugated, ridged hyperkeratosis especially flexures (cobblestone), malodour, secondary infection; KRT1 — palmoplantar keratoderma", "Histology: epidermolytic hyperkeratosis (vacuolar degeneration of upper epidermis, coarse keratohyaline granules); mosaic epidermolytic epidermal naevus parent → risk of generalised disease in child"]),
 ("Netherton syndrome — features.", ["Autosomal recessive SPINK5 (LEKTI deficiency → unopposed kallikrein activity): ichthyosis linearis circumflexa (migratory polycyclic double-edged scaly plaques) or congenital erythroderma, trichorrhexis invaginata ('bamboo hair' — eyebrows best), atopy (very high IgE, food allergy), failure to thrive, hypernatraemic dehydration, infections", "Caution: high systemic absorption of topical tacrolimus/steroids; IVIG, IL-17/IL-4R biologics (case reports)"]),
 ("Sjögren–Larsson syndrome.", ["Autosomal recessive ALDH3A2 (fatty aldehyde dehydrogenase) deficiency: ichthyosis (yellow-brown velvety, flexural), spastic diplegia/ tetraplegia, intellectual disability, glistening white dots in the retina (perifoveal), itching; diagnosis — FALDH assay"]),
 ("Refsum disease — features and treatment.", ["Autosomal recessive PHYH (phytanoyl-CoA hydroxylase) — phytanic acid accumulation: adult onset ichthyosis (vulgaris-like), retinitis pigmentosa (night blindness), anosmia, peripheral neuropathy, cerebellar ataxia, deafness, cardiac arrhythmia, short 4th metatarsal", "Treatment: phytanic acid-restricted diet (avoid dairy, ruminant fat, fish), plasmapheresis during crisis"]),
 ("What is KID syndrome?", ["Keratitis–Ichthyosis–Deafness — GJB2 (connexin 26) dominant mutation: erythrokeratoderma-like plaques, spiny hyperkeratosis, PPK (leather-like), vascularising keratitis (blindness), sensorineural deafness, infections, SCC risk"]),
 ("What is Conradi–Hünermann–Happle syndrome?", ["X-linked dominant chondrodysplasia punctata (EBP mutation), girls: ichthyosiform erythroderma at birth along Blaschko's lines → follicular atrophoderma, patchy cicatricial alopecia, cataracts, short limbs, stippled epiphyses on X-ray"]),
 ("What is CHILD syndrome?", ["Congenital Hemidysplasia with Ichthyosiform erythroderma and Limb Defects — X-linked dominant NSDHL mutation; unilateral (usually right) inflammatory ichthyosiform naevus with sharp midline demarcation, ipsilateral limb defects; topical statin + cholesterol therapy helps"]),
 ("Describe topical therapy in ichthyosis.", ["Emollients and humectants: petrolatum, urea 5–20% (stings in children), lactic acid 5–12%, glycerol, propylene glycol 40–60% under occlusion; keratolytics: salicylic acid (avoid large areas in infants — salicylism), α-hydroxy acids, N-acetylcysteine; topical retinoids (tazarotene) for localised thick scale; bathing with oils/ baking soda, mechanical scale removal (pumice)"]),
 ("Systemic retinoids in ichthyosis.", ["Acitretin 0.25–0.5 mg/kg/day for ARCI, epidermolytic (lower doses — may increase fragility), harlequin; isotretinoin alternative; side effects — teratogenicity (contraception 3 years after acitretin), mucocutaneous dryness, hyperlipidaemia, hepatotoxicity, skeletal hyperostosis/ premature epiphyseal closure in children (monitor growth, X-rays)"]),
 ("What genetic counselling issues arise?", ["X-linked: carrier mothers have 50% risk of affected sons; AR: 25% recurrence; AD (IV, epidermolytic): 50%; prenatal diagnosis by mutation testing/ fetal skin biopsy (historical); consanguinity counselling"]),
 ("Complications of severe ichthyosis.", ["Heat intolerance and hypohidrosis (hyperthermia), ectropion/ exposure keratitis, ear canal blockage, hearing loss, growth failure, vitamin D deficiency/ rickets (reduced UV synthesis), infections, contractures, psychosocial impact"]),
 ]),
dict(case="Neurofibromatosis type 1", qa=[
 ("What are the types of neurofibromas?", ["Cutaneous (dermal) — soft, sessile/ pedunculated, 'button-hole' sign (invaginate on pressure), appear from puberty, increase in pregnancy", "Subcutaneous — firm, tender nodules along peripheral nerves (higher MPNST risk)", "Plexiform — congenital, diffuse, 'bag of worms', overlying hyperpigmentation/ hypertrichosis, can cause disfigurement and overgrowth; ~10% MPNST lifetime", "Spinal/ internal neurofibromas"]),
 ("What is the button-hole sign?", ["Pressing a soft cutaneous neurofibroma pushes it into the dermis through a defect felt like a button-hole; it pops out on release — differentiates from other soft tumours (lipomas, skin tags)"]),
 ("Describe the eye findings in NF1.", ["Lisch nodules (iris hamartomas — >90% adults), optic pathway glioma (15% children, usually <7 y — visual loss, proptosis, precocious puberty), choroidal abnormalities (bright patchy nodules on NIR imaging — newer criterion), plexiform neurofibroma of eyelid (S-shaped lid), glaucoma, sphenoid wing dysplasia"]),
 ("What are the neurological and cognitive features?", ["Learning disabilities (~50–60%), ADHD, autism spectrum features, macrocephaly, epilepsy, hydrocephalus (aqueductal stenosis), headaches, 'unidentified bright objects' (T2 hyperintensities) on MRI, optic glioma, other gliomas (brainstem), Moyamoya"]),
 ("What tumours are associated with NF1?", ["Optic pathway glioma, other gliomas, MPNST, gastrointestinal stromal tumour (GIST), phaeochromocytoma, carcinoid (duodenal somatostatinoma), juvenile myelomonocytic leukaemia (with JXG), rhabdomyosarcoma, breast cancer (women <50 — screen from 30 y), glomus tumours of digits"]),
 ("What is the relationship between NF1, JXG and JMML?", ["Children with NF1 and juvenile xanthogranulomas were once thought to have a markedly higher risk of juvenile myelomonocytic leukaemia; current evidence suggests the added risk is small — routine haematological screening is not mandatory, but examine for hepatosplenomegaly and check CBC if symptomatic"]),
 ("What is Legius syndrome and segmental NF?", ["Legius: SPRED1 mutation — CALMs and axillary freckling, macrocephaly, learning issues but no neurofibromas, Lisch nodules or tumours; genetic test differentiates from NF1", "Segmental (mosaic) NF1: features confined to one body segment from post-zygotic mutation; risk of transmitting full NF1 if gonadal mosaicism"]),
 ("NF2 — key differences.", ["NF2 (now 'NF2-related schwannomatosis'): NF2 gene (merlin) chromosome 22; bilateral vestibular schwannomas (hearing loss, tinnitus, imbalance), meningiomas, ependymomas, juvenile posterior subcapsular cataract; few CALMs, cutaneous schwannomas (plaque-like); bevacizumab for vestibular schwannomas"]),
 ("Describe the management of cutaneous neurofibromas.", ["Surgical excision of symptomatic/ disfiguring lesions, CO2 laser/ electrodesiccation for multiple small ones, radiofrequency ablation; MEK inhibitors (selumetinib) shrink some cutaneous neurofibromas — topical MEK inhibitors under trial; psychological support"]),
 ("Pregnancy in NF1.", ["Neurofibromas may increase in number and size; higher risk of hypertension, pre-eclampsia, caesarean delivery; prenatal or pre-implantation genetic diagnosis available; 50% transmission risk"]),
 ("Cardiovascular features.", ["Hypertension (essential, renal artery stenosis, phaeochromocytoma, coarctation), NF1 vasculopathy (stenoses, aneurysms, Moyamoya), pulmonary stenosis (also Noonan overlap — NF1–Noonan syndrome)"]),
 ("Histopathology of plexiform neurofibroma vs MPNST.", ["Plexiform: tortuous expanded nerve fascicles with myxoid stroma, S100/SOX10-positive Schwann cells, CD34+ fibroblasts", "MPNST: hypercellular fascicles of atypical spindle cells, mitoses, necrosis, loss of S100/SOX10 and H3K27me3"]),
 ("How do you counsel parents of a child with NF1?", ["Explain AD inheritance (50% risk to each child), variable severity even within a family, regular annual reviews, signs needing urgent review (vision changes, new pain, rapid lump growth, headaches, precocious puberty, BP rise), school support for learning difficulties, NF support groups"]),
 ("What is the role of mosaic and NF1 microdeletion syndrome?", ["Whole-gene 17q11.2 microdeletion (5–10%): more severe — earlier and more numerous neurofibromas, facial dysmorphism, intellectual disability, overgrowth, higher MPNST risk", "Missense 'p.Met1149' or 'p.Arg1809' variants — mild phenotype without neurofibromas (pigmentary only)"]),
 ("Differential diagnosis of multiple neurofibroma-like tumours.", ["Multiple lipomas (familial lipomatosis), schwannomatosis (painful schwannomas — SMARCB1/LZTR1), Proteus syndrome, Cowden syndrome, multiple endocrine neoplasia 2B (mucosal neuromas), multiple dermatofibromas, cutaneous leiomyomas (Reed syndrome)"]),
 ("What is the prognosis/life expectancy in NF1?", ["Life expectancy reduced by ~10–15 years mainly due to MPNST, other malignancies, and vascular disease; most patients live productive lives with surveillance"]),
 ("Why is NF1 called a RASopathy?", ["Neurofibromin is a RAS-GAP; its loss increases RAS-GTP and downstream MAPK/ mTOR signalling — like other RASopathies (Noonan, Costello, cardiofaciocutaneous, Legius); explains overlapping features and use of MEK inhibitors"]),
 ]),
dict(case="Tuberous sclerosis complex", qa=[
 ("Explain the genetics and molecular basis.", ["Autosomal dominant; TSC1 (hamartin, 9q34) or TSC2 (tuberin, 16p13 — more severe, ~70%); two-thirds are de novo", "Hamartin–tuberin complex inhibits Rheb → mTORC1; loss → mTOR overactivation → cell growth, hamartomas in skin, brain, kidney, heart, lung — basis of mTOR inhibitors (sirolimus, everolimus)", "TSC2–PKD1 contiguous gene deletion → early severe polycystic kidney disease"]),
 ("Give the 2021 updated diagnostic criteria (International TSC Consensus).", ["Major (11): hypomelanotic macules (≥3, ≥5 mm), angiofibromas (≥3) or fibrous cephalic plaque, ungual fibromas (≥2), shagreen patch, multiple retinal hamartomas, multiple cortical tubers and/or radial migration lines, subependymal nodules (≥2), subependymal giant cell astrocytoma, cardiac rhabdomyoma, lymphangioleiomyomatosis (LAM), angiomyolipomas (≥2)", "Minor (7): 'confetti' skin lesions, dental enamel pits (>3), intraoral fibromas (≥2), retinal achromic patch, multiple renal cysts, non-renal hamartomas, sclerotic bone lesions", "Definite: 2 major or 1 major + ≥2 minor, or pathogenic TSC1/TSC2 variant; possible: 1 major or ≥2 minor (LAM + AML alone doesn't count as definite)"]),
 ("Describe the hypomelanotic macules in detail.", ["Earliest skin sign — at birth/infancy in ~90%: ash-leaf (lance-ovate), polygonal, thumbprint, confetti (tiny 1–3 mm on extremities); better seen with Wood's lamp; also poliosis (white hair tuft)", "Histology: normal melanocyte number with reduced melanin and smaller melanosomes"]),
 ("Facial angiofibromas — treatment.", ["Appear at 3–10 years, increase at puberty: red papules on nasolabial folds, cheeks, chin (sparing upper lip)", "Topical sirolimus (rapamycin) 0.1–1% gel/ointment daily — first-line, best when started early; maintenance needed", "Procedures: pulsed-dye laser (erythema), CO2/ Er:YAG ablation, shave/ electrosurgery, dermabrasion for established fibrotic lesions; recurrence common"]),
 ("What are ungual fibromas (Koenen tumours)?", ["Flesh-coloured firm papules emerging from proximal nail fold (periungual) or under the nail (subungual) — appear after puberty; produce longitudinal nail groove; more on toes; treated by excision when painful; single lesion can occur after trauma in normal people"]),
 ("Describe the neurological features.", ["Epilepsy in ~85% (infantile spasms in ~1/3 — vigabatrin first-line; drug-resistant epilepsy common; everolimus, cannabidiol, epilepsy surgery), cortical tubers, subependymal nodules, SEGA (near foramen of Monro — hydrocephalus; everolimus/ surgery), TSC-associated neuropsychiatric disorders (TAND — intellectual disability, autism, ADHD, anxiety)"]),
 ("Renal and pulmonary features.", ["Angiomyolipomas (~80% adults) — risk of haemorrhage when >3 cm (Wunderlich syndrome); treat with everolimus or embolisation; renal cysts, renal cell carcinoma (rare), CKD", "Lymphangioleiomyomatosis (LAM) — women of reproductive age, cystic lung disease, pneumothorax, chylous effusion; sirolimus stabilises lung function"]),
 ("Cardiac rhabdomyomas — relevance.", ["Detected antenatally (often the first clue to TSC on fetal echo); usually regress in infancy; may cause arrhythmias (WPW) or outflow obstruction in neonates"]),
 ("Ophthalmic and dental features.", ["Retinal astrocytic hamartomas ('mulberry' or flat translucent), retinal achromic patches; dental enamel pits (best seen with dental dye), gingival fibromas — oral exam essential"]),
 ("What is the fibrous cephalic plaque?", ["Raised, yellow-brown/ skin-coloured rubbery plaque on forehead/scalp (collagenoma) — often the first visible lesion after hypomelanotic macules; counts as major criterion with angiofibromas"]),
 ("Surveillance recommendations.", ["Brain MRI every 1–3 years until age 25 (SEGA), EEG in infants (subclinical seizures), TAND screening yearly, abdominal MRI every 1–3 years for AML, BP and renal function yearly, chest HRCT in women at 18 y (LAM), ECG/echo at baseline, dermatology and dental review yearly, ophthalmology baseline"]),
 ("Differential diagnosis of facial angiofibromas.", ["Acne vulgaris (comedones, pustules), rosacea, trichoepitheliomas (Brooke–Spiegler), Birt–Hogg–Dubé fibrofolliculomas, MEN1 angiofibromas, multiple syringomas, sebaceous adenomas (Muir–Torre), tricholemmomas (Cowden)"]),
 ("What is the histopathology of angiofibroma and shagreen patch?", ["Angiofibroma: dermal fibrosis with stellate/ plump fibroblasts, dilated vessels, perifollicular fibrosis, atrophic follicles", "Shagreen patch: connective tissue naevus (collagenoma) — thickened dense collagen bundles, reduced elastic fibres"]),
 ("Systemic mTOR inhibitors — use and side effects.", ["Everolimus: SEGA, renal AML (>3 cm), refractory epilepsy; sirolimus: LAM; also improve skin lesions", "Side effects: stomatitis/ mouth ulcers, acne-like eruptions, hyperlipidaemia, hyperglycaemia, infections, impaired wound healing, proteinuria, pneumonitis"]),
 ("Genetic counselling in TSC.", ["50% risk to offspring of affected parent; de novo in ~2/3 but parents should be examined (mild features, gonadal mosaicism ~2%); prenatal/ pre-implantation testing possible"]),
 ("How does TSC present at different ages?", ["Fetus/newborn: cardiac rhabdomyoma, hypomelanotic macules", "Infancy: infantile spasms, developmental delay, ash-leaf macules", "Childhood: angiofibromas, shagreen patch, autism/ learning difficulties", "Adolescence/adult: ungual fibromas, renal AML, LAM in women"]),
 ("Classify multiple tumour/ hamartoma syndromes with skin markers.", ["TSC (angiofibromas), NF1 (neurofibromas), Cowden/ PTEN hamartoma (trichilemmomas, acral keratoses, oral papillomas — breast/thyroid/endometrial cancer), Birt–Hogg–Dubé (fibrofolliculomas — renal cancer, pneumothorax), Gorlin (BCCs, palmar pits), Muir–Torre (sebaceous tumours — colorectal cancer), Gardner (epidermoid cysts, osteomas — colon polyps), MEN1 (angiofibromas, collagenomas), MEN2B (mucosal neuromas), Carney complex (lentigines, myxomas), Brooke–Spiegler (cylindromas, trichoepitheliomas)"]),
 ("What is the prognosis?", ["Variable; main causes of morbidity/mortality — renal disease (AML haemorrhage, CKD), status epilepticus/ SUDEP, SEGA, LAM; most live into adulthood with surveillance"]),
 ]),
]
